// the logo: a breath swelling into the hit at 1 s, a sub, a C major bell chord, a long room
const HIT = 1, hz = (m) => 440 * Math.pow(2, (m - 69) / 12);
const ir = ctx.createBuffer(2, 48000 * 3.5, 48000);
for (let c = 0; c < 2; c++) { const d = ir.getChannelData(c); for (let i = 0; i < d.length; i++) d[i] = (kit.random() * 2 - 1) * Math.pow(1 - i / d.length, 2.2); }
const room = ctx.createConvolver(); room.buffer = ir; const send = ctx.createGain(); send.gain.value = 0.4; send.connect(room).connect(ctx.destination);
const n = kit.noise('pink', HIT), f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.Q.value = 1;
kit.env(f.frequency, [[0, 300], [HIT, 5000]], 'exp');
const gn = ctx.createGain(); kit.env(gn.gain, [[0, 0.001], [HIT - 0.01, 0.4], [HIT, 0.0001]], 'exp');
n.connect(f).connect(gn).connect(ctx.destination); n.start(0);
const s = ctx.createOscillator(); kit.env(s.frequency, [[HIT, 70], [HIT + 0.5, 32.7]], 'exp');
const gs = ctx.createGain(); gs.gain.setValueAtTime(0, HIT); gs.gain.linearRampToValueAtTime(0.9, HIT + 0.005); gs.gain.setTargetAtTime(0, HIT + 0.1, 0.7);
s.connect(gs).connect(ctx.destination); s.start(HIT); s.stop(5.5);
for (const [m, d, v] of [[72, 0, 1], [76, 0.02, 0.8], [79, 0.04, 0.7], [86, 0.07, 0.55], [91, 0.1, 0.35]]) {
  const t = HIT + d, c = ctx.createOscillator(), mod = ctx.createOscillator(), depth = ctx.createGain(), g = ctx.createGain();
  c.frequency.value = hz(m); mod.frequency.value = hz(m) * 3.5;
  kit.env(depth.gain, [[t, hz(m) * 1.4], [t + 2, 1]], 'exp');
  mod.connect(depth).connect(c.frequency);
  g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.22 * v, t + 0.004); g.gain.setTargetAtTime(0, t + 0.01, 0.9);
  c.connect(g); g.connect(ctx.destination); g.connect(send);
  c.start(t); mod.start(t); c.stop(5.5); mod.stop(5.5);
}
const crack = kit.noise('white', 0.6), hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 3000;
const gc = ctx.createGain(); gc.gain.setValueAtTime(0, HIT); gc.gain.linearRampToValueAtTime(0.5, HIT + 0.002); gc.gain.setTargetAtTime(0, HIT + 0.005, 0.15);
crack.connect(hp).connect(gc); gc.connect(ctx.destination); gc.connect(send); crack.start(HIT);
